function endGame(){gameOver=true;notify('A cidade caiu · toque no campo para reiniciar');$('cmdstatus').textContent='A última linha foi rompida.'}
function rr(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function drawGround(){ctx.fillStyle='#414c37';ctx.fillRect(0,0,W,H);const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#4c5841');g.addColorStop(.52,'#46513a');g.addColorStop(1,'#394735');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.globalAlpha=.16;for(let x=0;x<W;x+=74){ctx.strokeStyle='#b0b68a';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=0;y<H;y+=72){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.globalAlpha=1;
// broken asphalt approach
ctx.fillStyle='#313b35';ctx.fillRect(208,290,992,80);ctx.fillStyle='#ffffff0b';ctx.fillRect(208,290,992,3);ctx.fillRect(208,367,992,3);ctx.setLineDash([25,22]);ctx.strokeStyle='#c9c19a55';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(212,330);ctx.lineTo(W,330);ctx.stroke();ctx.setLineDash([]);
for(const d of decor){ctx.globalAlpha=d.kind==='grass'?.2:.18;ctx.fillStyle=d.kind==='grass'?'#c2cb85':'#d0c4a0';ctx.beginPath();ctx.arc(d.x,d.y,d.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
// city boundary wall + gate
ctx.fillStyle='#252e2a';ctx.fillRect(206,0,16,270);ctx.fillRect(206,390,16,260);ctx.fillStyle='#667060';for(let y=12;y<270;y+=28){ctx.fillRect(204,y,20,5)}for(let y=402;y<650;y+=28){ctx.fillRect(204,y,20,5)}ctx.fillStyle='#d3b87c';ctx.fillRect(211,300,5,60);ctx.fillStyle='#f0ce84';ctx.fillRect(209,312,9,3);ctx.fillRect(209,345,9,3);
// city blocks
const buildings=[{x:22,y:45,w:115,h:74,c:'#697064'},{x:85,y:149,w:95,h:78,c:'#807a68'},{x:18,y:415,w:130,h:91,c:'#77766a'},{x:111,y:532,w:80,h:73,c:'#6a7569'},{x:35,y:254,w:103,h:34,c:'#6d786c'}];for(const b of buildings){ctx.fillStyle='#171d1b55';ctx.fillRect(b.x+7,b.y+8,b.w,b.h);rr(b.x,b.y,b.w,b.h,4,b.c,'#a4a28a66');ctx.fillStyle='#4a554f';for(let x=b.x+12;x<b.x+b.w-5;x+=22)for(let y=b.y+12;y<b.y+b.h-8;y+=19){ctx.fillRect(x,y,10,8);ctx.fillStyle='#b38c5a';ctx.fillRect(x+3,y+2,3,4);ctx.fillStyle='#4a554f'}ctx.fillStyle='#948b72';ctx.fillRect(b.x+4,b.y+4,b.w-8,5);ctx.fillStyle='#2e3732';ctx.fillRect(b.x+b.w*.4,b.y+b.h-17,14,17)}
// defensive floodlights
for(const y of [145,500]){ctx.strokeStyle='#bcc99a99';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(226,y);ctx.lineTo(410,y-55);ctx.lineTo(410,y+55);ctx.stroke();ctx.fillStyle='#f6d990';ctx.beginPath();ctx.arc(227,y,4,0,Math.PI*2);ctx.fill()}
// environment props
for(const p of props){if(p.dead)continue;if(p.type==='tree'){ctx.fillStyle='#20281e55';ctx.beginPath();ctx.ellipse(p.x+5,p.y+6,p.r*1.1,p.r*.7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#4c623b';ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#77864c';ctx.beginPath();ctx.arc(p.x-p.r*.25,p.y-p.r*.27,p.r*.57,0,Math.PI*2);ctx.fill();ctx.fillStyle='#97a064';ctx.beginPath();ctx.arc(p.x-p.r*.2,p.y-p.r*.5,p.r*.22,0,Math.PI*2);ctx.fill()}else{ctx.save();ctx.translate(p.x,p.y);ctx.rotate(-.08);rr(-p.r,-p.r*.45,p.r*2,p.r*.9,3,'#59645e','#a6ad9866');ctx.fillStyle='#d9c67f';ctx.fillRect(-p.r*.63,-p.r*.25,p.r*.33,p.r*.13);ctx.fillRect(p.r*.3,-p.r*.25,p.r*.33,p.r*.13);ctx.restore()}}
for(const w of wrecks){if(w.type==='unit'){ctx.globalAlpha=.55;ctx.fillStyle='#222522';ctx.beginPath();ctx.ellipse(w.x,w.y+4,15,7,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}else{ctx.globalAlpha=.7;ctx.fillStyle='#302d26';ctx.beginPath();ctx.ellipse(w.x,w.y,10,5,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}}
// perimeter marker and sector grid accents
ctx.strokeStyle='#d3e2aa22';ctx.setLineDash([5,7]);ctx.strokeRect(231,18,950,614);ctx.setLineDash([]);ctx.fillStyle='#bdd37b';ctx.globalAlpha=.6;ctx.font='9px system-ui';ctx.fillText('ZONA DE DEFESA',241,34);ctx.globalAlpha=1;
}
function drawUnit(u){if(!u.alive)return;const t=u.type;ctx.save();ctx.translate(u.x,u.y);if(t.kind==='heli'||t.kind==='apache'){ctx.translate(0,Math.sin(u.alt)*2-5)}if(u===selected){ctx.strokeStyle='#d6fa84';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,2,18,10,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#d6fa84';ctx.beginPath();ctx.moveTo(0,-24);ctx.lineTo(-5,-32);ctx.lineTo(5,-32);ctx.fill()}
ctx.rotate(u.angle||0);ctx.fillStyle='#151a16a8';ctx.beginPath();ctx.ellipse(2,7,t.kind==='tank'?19:14,7,0,0,Math.PI*2);ctx.fill();
if(t.kind==='soldier'||t.kind==='para'){ctx.rotate(-u.angle||0);ctx.fillStyle='#29352c';ctx.beginPath();ctx.ellipse(0,0,7,10,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=t.color;ctx.beginPath();ctx.ellipse(0,0,6,9,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#c4b987';ctx.beginPath();ctx.arc(0,-5,4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#242923';ctx.fillRect(4,-2,11,2);ctx.fillStyle='#d4c985';ctx.fillRect(-4,1,3,3);ctx.fillRect(2,1,3,3)}
else if(t.kind==='vehicle'||t.kind==='tank'||t.kind==='arty'){ctx.fillStyle='#252e28';rr(-17,-9,34,18,5,'#303a32','#a0a785');ctx.fillStyle=t.color;rr(-14,-7,28,14,4,t.color,'#aab390');for(const x of [-11,9]){ctx.fillStyle='#252a25';ctx.fillRect(x,-10,5,20);ctx.fillStyle='#7d886d';ctx.fillRect(x+1,-8,2,16)}if(t.kind==='tank'||t.kind==='arty'){ctx.fillStyle='#657257';ctx.beginPath();ctx.ellipse(-1,0,8,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#a1a982';ctx.fillRect(0,-2,19,4);ctx.fillStyle='#272e27';ctx.fillRect(12,-1,8,2)}else{ctx.fillStyle='#b3b58a';ctx.fillRect(2,-4,9,2);ctx.fillRect(2,3,9,2)}}
else if(t.kind==='heli'||t.kind==='apache'){ctx.fillStyle=t.kind==='apache'?'#646e47':'#859675';ctx.beginPath();ctx.ellipse(0,0,16,8,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#bbc8a0';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-20,-1);ctx.lineTo(20,-1);ctx.moveTo(0,-2);ctx.lineTo(0,-16);ctx.moveTo(-24,-15);ctx.lineTo(24,-15);ctx.stroke();ctx.fillStyle='#b5c2a6';ctx.fillRect(12,-2,10,2);ctx.fillStyle='#242a25';ctx.beginPath();ctx.ellipse(0,0,7,5,0,0,Math.PI*2);ctx.fill()}
else if(t.kind==='jet'){ctx.fillStyle='#b6c0a3';ctx.beginPath();ctx.moveTo(18,0);ctx.lineTo(-7,-3);ctx.lineTo(-13,-12);ctx.lineTo(-17,-12);ctx.lineTo(-14,-2);ctx.lineTo(-23,0);ctx.lineTo(-14,3);ctx.lineTo(-17,11);ctx.lineTo(-12,10);ctx.lineTo(-6,3);ctx.closePath();ctx.fill();ctx.fillStyle='#ecb45c';ctx.fillRect(-23,-2,5,4)}
// health strip
ctx.rotate(-(u.angle||0));ctx.fillStyle='#172019cc';ctx.fillRect(-13,-20,26,3);ctx.fillStyle=u.hp/u.maxHp>.45?'#a9d66b':'#ed7660';ctx.fillRect(-12,-19,24*Math.max(0,u.hp/u.maxHp),1.5);ctx.restore()}
function drawZombie(z){if(!z.alive)return;ctx.save();ctx.translate(z.x,z.y);ctx.rotate(Math.sin(z.anim*.6)*.08);ctx.fillStyle='#222b2380';ctx.beginPath();ctx.ellipse(1,7,10,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=z.variant>.65?'#77785a':'#85896a';ctx.beginPath();ctx.ellipse(0,0,7,11,Math.sin(z.anim)*.12,0,Math.PI*2);ctx.fill();ctx.fillStyle='#555d48';ctx.beginPath();ctx.arc(0,-8,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d7c4a0';ctx.fillRect(-3,-9,2,2);ctx.fillRect(2,-9,2,2);ctx.strokeStyle='#353b2f';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-4,1);ctx.lineTo(-10,6+Math.sin(z.anim)*2);ctx.moveTo(4,1);ctx.lineTo(10,4-Math.sin(z.anim)*2);ctx.stroke();ctx.fillStyle='#20281f';ctx.fillRect(-6,-18,12,2);ctx.fillStyle='#e77863';ctx.fillRect(-6,-18,12*Math.max(0,z.hp/z.maxHp),2);ctx.restore()}

