Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -42,9 +42,10 @@
 function makeUnit(t,x,y){const u={type:t,x,y,tx:x,ty:y,hp:t.hp,maxHp:t.hp,cool:Math.random()*.3,angle:0,selected:false,alive:true,alt:0,deploy:0};units.push(u);if(t.kind==='med'){for(let i=0;i<2;i++)units.push({type:{...types[0],name:'Resgatado'},x:x-15+i*30,y:y+25,tx:x-15+i*30,ty:y+25,hp:75,maxHp:75,cool:0,angle:0,alive:true})}if(t.kind==='para'){for(let i=0;i<3;i++)units.push({type:{...types[0],name:'Paraquedista'},x:x-20+i*20,y:y+28,tx:x-20+i*20,ty:y+28,hp:75,maxHp:75,cool:0,angle:0,alive:true,deploy:1})}return u}
 function nearestTarget(u){let best=null,bd=u.type.range;for(const z of zombies){if(!z.alive)continue;const d=Math.hypot(z.x-u.x,z.y-u.y);if(d<bd){bd=d;best=z}}return best}
